values(3,'listening','IELTS Listening Test 208','published',$json${"version":"listening-test-208-v1","test_code":"TEST-208","audio_url":"https://ia903208.us.archive.org/0/items/test-208-100-percent-mp-3/TEST_208_100_PERCENT_MP3.mp3","total_questions":40,"audio_once":true,"sections":[{"number":1,"label":"SECTION 1","range":"Questions 1–10","blocks":[{"kind":"notes","range":"Questions 1–10","instruction":"Complete the notes below.","word_limit":"Write ONE WORD AND/OR A NUMBER for each answer.","title":"Ferry to Shetland Islands","items":[["Name of ferry company: ",{"q":1}," Ferries"],["Ferries depart seven times per ",{"q":2}," in summer"],["Cost for four people with car: a little less than £ ",{"q":3}],["Cancellation policy: receive a ",{"q":4}," (if cancelled a month in advance)"],["Cabins: book one with a ",{"q":5},"; luxury cabins have a TV"],["Bring snacks and ",{"q":6}," for the children"],["A ",{"q":7}," is required for the dog kennels"],["Try to see ",{"q":8}," in the morning"],["If time, visit ",{"q":9}," Castle"],["The ",{"q":10}," restaurant in a nearby village is recommended"]]}]},{"number":2,"label":"SECTION 2","range":"Questions 11–20","blocks":[{"kind":"choose_two","range":"Questions 11 and 12","instruction":"Choose TWO letters, A–E.","question":"Which TWO explanations for the popularity of street food are given?","questions":[11,12],"options":{"A":"low price","B":"locally sourced","C":"freshly made","D":"convenience","E":"unusual food"}},{"kind":"choose_two","range":"Questions 13 and 14","instruction":"Choose TWO letters, A–E.","question":"Which TWO places are recommended for new street food businesses?","questions":[13,14],"options":{"A":"music festivals","B":"food markets","C":"weddings","D":"parties","E":"parks"}},{"kind":"mcq","range":"Questions 15–16","instruction":"Choose the correct letter, A, B or C.","title":"Street food business","questions":[{"q":15,"text":"What does the speaker say about getting equipment for a street food business?","options":{"A":"High quality equipment is a good investment.","B":"It's best to buy second-hand equipment.","C":"Renting equipment can be cheap."}},{"q":16,"text":"What advice is given about creating a product for a street food business?","options":{"A":"Provide information about the ingredients.","B":"It is important to have an original product.","C":"The presentation is an important factor."}}]},{"kind":"matching","range":"Questions 17–20","instruction":"What problem did the owners of each of the following street food businesses experience?","word_limit":"Choose FOUR answers from the box and write the correct letter, A–F, next to Questions 17–20.","title":"Street food businesses","choices":{"A":"Some ingredients were too expensive.","B":"The meals took a long time to prepare.","C":"They had no money for marketing.","D":"It was difficult to get a permit to sell food.","E":"A competitor was selling similar food in their area.","F":"They worked very long hours."},"items":[{"q":17,"text":"Thai Basil"},{"q":18,"text":"Basque"},{"q":19,"text":"Lou's kitchen"},{"q":20,"text":"Chip Chop"}]}]},{"number":3,"label":"SECTION 3","range":"Questions 21–30","blocks":[{"kind":"choose_two","range":"Questions 21 and 22","instruction":"Choose TWO letters, A–E.","question":"Which TWO points do the speakers make about the terms 'ethical' and 'sustainable' fashion?","questions":[21,22],"options":{"A":"Their definitions keep changing.","B":"People think they mean the same thing.","C":"The term 'eco-friendly' is preferable.","D":"They are often used imprecisely.","E":"Companies should avoid using them on clothing labels."}},{"kind":"choose_two","range":"Questions 23 and 24","instruction":"Choose TWO letters, A–E.","question":"Which TWO claims about wool production do the speakers disagree with?","questions":[23,24],"options":{"A":"Sheep are generally well-treated.","B":"Wool is easy to recycle.","C":"Wool is a long-lasting fabric.","D":"Wool production involves few chemicals.","E":"Sheep do less environmental damage than other livestock."}},{"kind":"matching","range":"Questions 25–30","instruction":"What comment do the speakers make about each of the following semi-synthetic fabrics?","word_limit":"Choose SIX answers from the box and write the correct letter, A–H, next to Questions 25–30.","title":"Semi-synthetic fabrics","choices":{"A":"The production process is fuel efficient.","B":"It is the least sustainable of alternative fabrics.","C":"Production costs are high.","D":"It provides additional health benefits.","E":"It is not durable in the long-term.","F":"It needs to be produced in a certain way to be sustainable.","G":"Chemicals required for production can be reused.","H":"This is from a wholly sustainable source."},"items":[{"q":25,"text":"Lyocell"},{"q":26,"text":"Cupro"},{"q":27,"text":"Bamboo"},{"q":28,"text":"EcoVero"},{"q":29,"text":"Cork"},{"q":30,"text":"Hemp"}]}]},{"number":4,"label":"SECTION 4","range":"Questions 31–40","blocks":[{"kind":"notes_groups","range":"Questions 31–40","instruction":"Complete the notes below.","word_limit":"Write ONE WORD ONLY for each answer.","title":"Invasive species","groups":[{"heading":"Definition","intro":"An invasive species is an animal or plant that causes harm to an environment after being introduced by humans.","items":[]},{"heading":"An invasive species can be a problem when it:","items":[["eats native species."],["introduces a new ",{"q":31},"."],["takes food from native species."],["threatens an entire ",{"q":32},"."]]},{"heading":"How invasive species spread","items":[["accidentally, e.g. via people returning from their ",{"q":33}," or on cargo ships."],["intentionally, e.g. for pest control, or as ",{"q":34},"."]]},{"heading":"Examples of invasive species","items":[["Rhinella marina (toads) were introduced to Australia from Hawaii in 1935 to eat a type of insect that was damaging the ",{"q":35}," plantations."],["The toads failed to solve the problem, became widespread in northern Australia, are poisonous to predators, and reduce food available for native frogs."],["Japanese knotweed plants were popular among 19th-century gardeners in the UK."],["Rhododendron plants prevent ",{"q":36}," from reaching native plants."],["Grey squirrels from North America reduce food sources for the UK's native red squirrels and spread a ",{"q":37}," that kills red squirrels."]]},{"heading":"Tackling invasive species","items":[["Monitoring helps us to understand the ",{"q":38}," of invasive species and the impact they have."],["Setting up a national ",{"q":39}," makes it easier to track them."],["Asking the public to ",{"q":40}," and report them helps with monitoring."]]}]}]}],"answer_key":{"1":["Northern"],"2":["week"],"3":["250","two hundred and fifty","two hundred fifty"],"4":["voucher"],"5":["window"],"6":["books"],"7":["blanket"],"8":["dolphins"],"9":["Drum"],"10":["Italian"],"11":["C","E"],"12":["C","E"],"13":["B","E"],"14":["B","E"],"15":["B"],"16":["C"],"17":["F"],"18":["A"],"19":["B"],"20":["D"],"21":["B","D"],"22":["B","D"],"23":["D","E"],"24":["D","E"],"25":["G"],"26":["B"],"27":["F"],"28":["A"],"29":["H"],"30":["D"],"31":["disease"],"32":["ecosystem"],"33":["holiday","holidays"],"34":["pets"],"35":["sugar"],"36":["light"],"37":["virus"],"38":["behaviour","behavior"],"39":["database"],"40":["photograph"]},"pair_groups":{"11-12":{"questions":[11,12],"correct":["C","E"]},"13-14":{"questions":[13,14],"correct":["B","E"]},"21-22":{"questions":[21,22],"correct":["B","D"]},"23-24":{"questions":[23,24],"correct":["D","E"]}}}$json$::jsonb,now(),now())
